import math
    import random
    import time

    LANGUAGE_WRAPPER = 'Let $p={p}$ be a prime and $c={c}$ be a positive integer. A positive integer $n$ is called a $(p,c)$-power tail if there exists a positive integer $m$ such that the exponent of $p$ in the prime factorization of $m!$ is exactly $n \\cdot c$. How many positive integers less than ${N}$ are not $(p,c)$-power tails?'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
p = rng.choice([3, 5, 7])
c = rng.randint(2, p)
N = rng.randint(500, 2500)
return {
    'p': p,
    'c': c,
    'N': N
}

    def verifier(assign):
p = assign['p']
c = assign['c']
N = assign['N']

# Validate constraints
if not isinstance(p, int) or not isinstance(c, int) or not isinstance(N, int):
    return False, None # Types must be int
if p not in [2, 3, 5, 7, 11, 13]: # Simplified primality check for typical choices
    for i in range(2, int(p**0.5) + 1):
        if p % i == 0:
            return False, None # p must be prime
if not (2 <= c <= p):
    return False, None # c must be in a reasonable range
if not (100 <= N <= 5000):
    return False, None # N must be in a reasonable range

limit = c * (N - 1)

weights = []
if p == 1: return False, None # p must be > 1
w = 1
while w <= limit:
    weights.append(w)
    if (limit - 1) // p < w: # Avoid overflow
        break
    w = w * p + 1

if not weights:
    return True, N - 1

K_rep = []
temp_K = limit
for w in reversed(weights):
    digit = temp_K // w
    K_rep.append(digit)
    temp_K %= w

K_rep.reverse() # least significant digit first
weights_mod_c = [w % c for w in weights]
memo = {}

def count_good_k(digit_idx, tight, remainder):
    if digit_idx == -1:
        return 1 if remainder == 0 else 0
    state = (digit_idx, tight, remainder)
    if state in memo:
        return memo[state]

    res = 0
    upper_bound = K_rep[digit_idx] if tight else p - 1

    for digit in range(upper_bound + 1):
        new_remainder = (remainder + digit * weights_mod_c[digit_idx]) % c
        new_tight = tight and (digit == upper_bound)
        res += count_good_k(digit_idx - 1, new_tight, new_remainder)

    memo[state] = res
    return res

# Count k in S_p such that k <= c*(N-1) and k is a multiple of c.
# S_p is the set of p-factorial tails.
num_good_k = count_good_k(len(K_rep) - 1, True, 0)

# k=0 is always counted, which corresponds to n=0. We need positive n.
num_good_n = num_good_k - 1

answer = (N - 1) - num_good_n
return True, answer


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

